def all_Characters_Same(s):
    # Remove spaces from the string
    cleaned_s = s.replace(" ", "")
    # Check if all characters are the same
    if not cleaned_s:
        return True  # Empty string after removing spaces
    first_char = cleaned_s[0]
    for char in cleaned_s:
        if char != first_char:
            return False
    return True
